#!/usr/bin/env bash
# Self-contained fix for SERVERPANEL.service. Everything needed (the full
# app source tree, including the envfiles module + fullscreen editor
# template) is embedded below as base64 — no separate zip to upload.
#
# Fixes:
#   - ModuleNotFoundError: models.user / services.firewall_service /
#     modules.envfiles.routes (files missing on disk)
#   - Ships the current .env Editor with the full-viewport layout
#
# NOT touched: venv/, backups/, data/, logs/, or your DB
# (DB lives outside this dir at /root/server-panel-data per config.py).
#
# Usage: run from inside /root/server-panel
#   chmod +x fix-servicepanel.sh
#   ./fix-servicepanel.sh
set -euo pipefail

if [ ! -f "app.py" ] && [ ! -d "modules" ]; then
  echo "This doesn't look like /root/server-panel (no app.py/modules here)." >&2
  exit 1
fi

APP_DIR="$(pwd)"
SERVICE="SERVERPANEL.service"
ts=$(date +%Y%m%d-%H%M%S)
PAYLOAD_ZIP="/tmp/full-restore-$ts.zip"

echo "==> Extracting embedded payload"
PAYLOAD_LINE=$(awk '/^__PAYLOAD_BELOW__$/{print NR + 1; exit}' "$0")
tail -n +"$PAYLOAD_LINE" "$0" | base64 -d > "$PAYLOAD_ZIP"

echo "==> Backing up current tree to backups/broken-full-$ts"
mkdir -p "backups/broken-full-$ts"
for d in app.py config.py extensions.py settings.py requirements.txt \
         agent_distribution database migrations models modules services \
         static systemd tasks templates utils; do
  if [ -e "$d" ]; then
    mkdir -p "backups/broken-full-$ts/$(dirname "$d")"
    cp -r "$d" "backups/broken-full-$ts/$d" 2>/dev/null || true
  fi
done

echo "==> Restoring full source tree"
unzip -o "$PAYLOAD_ZIP" -d "$APP_DIR" > /dev/null
rm -f "$PAYLOAD_ZIP"

echo "==> Clearing stale __pycache__"
find . -maxdepth 6 -type d -name __pycache__ -not -path "./venv/*" -exec rm -rf {} + 2>/dev/null || true

echo "==> Sanity check: do all restored .py files compile?"
if [ -x "venv/bin/python" ]; then PYBIN="venv/bin/python"; else PYBIN="python3"; fi
if "$PYBIN" -m compileall -q app.py config.py extensions.py settings.py \
    agent_distribution database migrations models modules services tasks utils; then
  echo "  OK  all restored files compile"
else
  echo "  STILL BROKEN — a restored file has a syntax error, see above."
  echo "  Broken tree is backed up in backups/broken-full-$ts"
  exit 1
fi

echo "==> Restarting $SERVICE"
systemctl restart "$SERVICE"
sleep 2
systemctl --no-pager --lines=0 status "$SERVICE" || true
echo "==> Last 20 log lines:"
journalctl -u "$SERVICE" -n 20 --no-pager

echo "==> Done. Broken files backed up at: $APP_DIR/backups/broken-full-$ts"
exit 0
__PAYLOAD_BELOW__
